def parse_ascii(value: str) -> tuple[bool, str]:
    try:
        value.encode('ascii')
    except UnicodeEncodeError:
        return False, 'ASCII characters required'
    if len(value) > 64:
        return False, 'maximum length is 64 characters'
    return True, value

